export type CloudProvider = "AWS" | "Azure" | "GCP" | "DigitalOcean" | "OCI" | "OVH" | "Alibaba";
export type OperatingSystem = "Linux" | "Windows";

export interface ComputeInstance {
  provider: CloudProvider;
  instanceType: string;
  os: OperatingSystem;
  vCPUs: number;
  memory: number; // GiB
  onDemandHourly: number | null;
  onDemandMonthly: number | null;
  spot: number | null;
  savingsPlan1yr: number | null;
  savingsPlan3yr: number | null;
  reserved1yr: number | null;
  reserved3yr: number | null;
}

/** The capability values the site publishes (its LLM schemaVersion 2.5). There
 *  is no "Code": the site assigned it to any model whose output cost $0.50 per
 *  1M tokens or more (225 of 292 models), a price threshold rather than a
 *  capability, and dropped it on 2026-10-05. Every other list of capabilities in
 *  this repo is built from this one. */
export const LLM_CAPABILITIES = ["Text", "Vision", "Reasoning", "Agents", "Image Gen", "Audio"] as const;
export type LLMCapability = (typeof LLM_CAPABILITIES)[number];
/** Price tier only. "Open Weights" used to live here and made openness and
 *  price mutually exclusive; openness is now its own axis, derived from the
 *  licence in ../lib/openness.ts. */
export type LLMCategory = "Frontier" | "Mid-tier" | "Budget" | "Image";

export interface LLMModel {
  provider: string;
  model: string;
  parameters?: string;
  inputPricePer1M: number;
  outputPricePer1M: number;
  /** Batch API pricing (typically -50%) */
  batchInputPricePer1M?: number;
  batchOutputPricePer1M?: number;
  /** Prompt-cache read price (typically ~10% of input) */
  cachedInputPricePer1M?: number;
  /** Prompt-cache WRITE price at the default (roughly 5-minute) lifetime, where
   *  the vendor publishes one, typically 1.25x input. Absent means "not
   *  published", which optimizedUseCaseCost() reads as "a write costs the
   *  ordinary input rate". Site API schemaVersion 2.3. */
  cacheWritePricePer1M?: number;
  contextWindow: string;
  category: LLMCategory;
  capabilities: LLMCapability[];
  releaseDate?: string;
  eloScore?: number;
  license?: string;
  /** True when the price above is an outlier listing: one host's rate with
   *  input near free and output at or above the going rate. Set by the site
   *  (schemaVersion 2.6) from its nightly per-host fan-out, which this server
   *  does not hold, so tiers 2 and 3 can only carry what a snapshot recorded.
   *  Absent means not flagged or unknown. Refuses the FinOps Friendly badge. */
  outlierListing?: boolean;
  /** True when the price above is a promotional rate: every host listing it
   *  marks it as a discount on its standard rate, or its maker publishes it
   *  with an end date. Set by the site (schemaVersion 2.7). The price is what
   *  is charged today, so it is labelled, not corrected. */
  promotionalListing?: boolean;
}

